// Package main -- emit_dsl.go: the generated MemQL tree.
//
// One file per mirrored type, holding the concept, its two writes and its two
// reads. Everything a domain needs is in one place, which is what makes the
// quarterly diff readable: a field added by Shopify shows up as one line in
// the concept and one in each write, in the same file, rather than scattered
// across four consolidated per-construct files.
package main

import (
	"fmt"
	"sort"
	"strings"
)

// generatedHeader is stamped on every emitted file. The wording matters: the
// instruction a reader needs is not "do not edit" on its own -- it is where
// to make the change instead.
func generatedHeader(version string) string {
	return `// Code generated by cmd/shopifyschema from Admin GraphQL ` + version + `. DO NOT EDIT.
//
// The model is GENERATED (design D1): the shape of a mirrored Shopify object
// is a property of the pinned API version, not of anyone's judgement, so it
// is read out of the schema rather than typed. To change what is here, change
// cmd/shopifyschema/allowlist.yaml or the mapping rules in
// cmd/shopifyschema/mapping.go and regenerate -- never this file. The drift
// gate (cmd/shopifyschema/shopify_schema_drift_test.go) fails the build on a
// hand edit, because a hand edit is lost the next time anybody regenerates.
`
}

// EmitConceptFile renders one type's .memql file.
func EmitConceptFile(version string, p *TypePlan) string {
	var b strings.Builder
	b.WriteString(generatedHeader(version))
	b.WriteString("//\n")
	b.WriteString(wrapComment(fmt.Sprintf(
		"Mirror of the Admin GraphQL %s type. Shopify owns these rows; MemQL holds a copy. "+
			"The row id is derived from (storeId, gid) so two stores mirroring the same numeric "+
			"object id stay separate rows, and `gid` carries Shopify's own identity. `updatedAt` "+
			"is the ORIGIN's version and the apply guard compares against it -- a webhook that "+
			"arrives late cannot overwrite a newer fetch.", p.GraphQLType)))
	if p.ParentType != "" {
		b.WriteString("//\n")
		b.WriteString(wrapComment(fmt.Sprintf(
			"Materialised from %s.%s: on a fetch through the nested selection, on a backfill "+
				"through the bulk stream's __parentId. `parentGid` carries the lineage.",
			p.ParentType, p.ParentConnection)))
	}
	b.WriteString("\n")

	// Imports: the shared not-deleted trait every live-rows read uses, and
	// the parent when there is one.
	if p.ParentConcept != "" && p.ParentConcept != p.Concept {
		fmt.Fprintf(&b, "use shopify.generated.%s.{ %s }\n", p.ParentConcept, p.ParentConcept)
	}
	b.WriteString("use common.traits.{ isNotDeleted }\n\n")

	// ---- the concept -------------------------------------------------
	b.WriteString(conceptDoc(p))
	b.WriteString("@namespace(\"shopify\")\n")
	b.WriteString("@origin(\"shopify\")\n")
	b.WriteString("@rowAuthz(clusterOwner)\n")
	fmt.Fprintf(&b, "@displayCard(primary=\"gid\", secondary=%q, status=\"deleted\")\n", displaySecondary(p))
	fmt.Fprintf(&b, "concept %s {\n", p.Concept)
	b.WriteString(mirrorColumns(p))
	for _, f := range p.Fields {
		b.WriteString(conceptField(f))
	}
	if p.ParentConcept != "" {
		fmt.Fprintf(&b, "\n  @relationship(type=\"parent\", as=%q, field=\"parentGid\", target=%s, direction=\"outgoing\")\n",
			childLabel(p), p.ParentConcept)
	}
	b.WriteString("}\n\n")

	b.WriteString(emitShape(p))
	b.WriteString(emitReads(p))
	return b.String()
}

// emitShape renders the EMPTY-BODY, signature-bound shape both reads project
// through.
//
// A read with no shape clause is not projected at all: the engine answers
// with the raw graph bundle, whose rows are node envelopes rather than the
// concept's fields. Every consumer would then have to know that -- and the
// one that did not would read empty and look like a store with no data. An
// empty-body shape bound to the concept is the engine's own default
// projection (memql#2035), so this is a declaration that the read returns
// the concept, not an enumeration that has to be kept in step with it.
func emitShape(p *TypePlan) string {
	var b strings.Builder
	b.WriteString(wrapDoc(fmt.Sprintf(
		"Every field of the mirrored %s. Empty body on purpose: that IS the default "+
			"projection over the bound concept, so a field the generator adds next quarter is "+
			"projected without a second edit.", p.GraphQLType)))
	b.WriteString("@row\n")
	fmt.Fprintf(&b, "shape %s %s {\n}\n\n", p.Concept, shapeName(p))
	return b.String()
}

func conceptDoc(p *TypePlan) string {
	return wrapDoc(fmt.Sprintf("Shopify %s, mirrored. Cluster-owner tier: commerce data is business data, not per-user data (design D5).", p.GraphQLType))
}

// displaySecondary picks the most name-like field for the row card, falling
// back to the origin version so a card is never blank.
func displaySecondary(p *TypePlan) string {
	for _, want := range []string{"name", "title", "handle", "displayName", "email", "legacyResourceId"} {
		for _, f := range p.Fields {
			if f.Name == want && f.DSLType == "string" {
				return want
			}
		}
	}
	return "updatedAt"
}

// childLabel is the `as=` label on the parent relationship: the DOMAIN
// meaning of the edge, which is open vocabulary, as distinct from the
// structural `type="parent"` the engine acts on (memql#3652).
func childLabel(p *TypePlan) string {
	return "partOf" + strings.ToUpper(p.ParentConcept[:1]) + p.ParentConcept[1:]
}

// mirrorColumns are the five (six with a parent) fields every mirror row
// carries regardless of type.
func mirrorColumns(p *TypePlan) string {
	var b strings.Builder
	b.WriteString("  /// The v1:shopify:store row this mirror belongs to. Every read is store-scoped.\n")
	b.WriteString("  storeId    string!\n")
	b.WriteString("  /// Shopify's own identity, gid://shopify/<Type>/<id>. Stable across renames.\n")
	b.WriteString("  gid        string!\n")
	b.WriteString("  /// The ORIGIN's version. A write whose updatedAt is older than the stored one is refused as stale.\n")
	b.WriteString("  updatedAt  datetime!\n")
	b.WriteString("  /// When MemQL last wrote this row. Drift is (now - syncedAt) and the store's health reports it.\n")
	b.WriteString("  syncedAt   datetime!\n")
	b.WriteString("  /// Tombstone. A delete topic, or a fetch that finds nothing, sets it; the row and its history stay.\n")
	b.WriteString("  deleted    bool\n")
	if p.ParentConcept != "" {
		b.WriteString("  /// The parent's GID, from the nested selection on a fetch and from __parentId on a bulk stream.\n")
		b.WriteString("  parentGid  string!\n")
	}
	return b.String()
}

func conceptField(f FieldPlan) string {
	var b strings.Builder
	doc := f.Doc
	if doc == "" {
		doc = fmt.Sprintf("Admin GraphQL %s.", f.GraphQL)
	} else {
		doc = fmt.Sprintf("Admin GraphQL %s. %s", f.GraphQL, doc)
	}
	for _, line := range wrapLines(doc, 72) {
		fmt.Fprintf(&b, "  /// %s\n", line)
	}
	fmt.Fprintf(&b, "  %s %s\n", pad(f.Name, 26), f.DSLType)
	return b.String()
}

// NO WRITE IS GENERATED, and that is the contract rather than an
// omission.
//
// A connector hands the runtime MirrorWrites and the runtime performs the
// write (component/datasync's EngineMirrorWriter), under the connector
// actor and behind the version guard. Emitting a mutation per concept
// would put a SECOND write path beside it -- 65 of them -- and the two
// would have to agree about stamping, about what a cleared field means
// and about which fields a retirement sets. They would not, and the
// disagreement would be a row written one way by a live delivery and
// another way by a reconciliation sweep.
//
// What is generated is everything a READER needs: the concept, its
// default projection, and the two reads reconciliation and the
// compliance export walk.

// emitReads renders the two reads every mirrored domain needs: one row by
// GID, and a store's live rows. Reconciliation walks the second to find what
// the origin no longer returns, and the compliance export walks it to collect
// everything referencing a customer.
func emitReads(p *TypePlan) string {
	var b strings.Builder
	b.WriteString(wrapDoc(fmt.Sprintf("One mirrored Shopify %s by store and GID.", p.GraphQLType)))
	b.WriteString("@actor\n")
	fmt.Fprintf(&b, "query %s %s {\n", p.Concept, byGidName(p))
	b.WriteString("  args {\n    storeId  string!\n    gid      string!\n  }\n")
	b.WriteString("  filter  storeId==args.storeId && gid==args.gid && actor.isClusterOwner==true\n")
	fmt.Fprintf(&b, "  shape   %s\n", shapeName(p))
	b.WriteString("}\n\n")

	b.WriteString(wrapDoc(fmt.Sprintf(
		"Live mirrored Shopify %s rows for one store, newest origin update first. `since` narrows "+
			"to what changed, which is how reconciliation pages without re-reading the whole domain.",
		p.GraphQLType)))
	b.WriteString("@actor\n")
	fmt.Fprintf(&b, "query %s %s {\n", p.Concept, forStoreName(p))
	b.WriteString("  args {\n    storeId  string!\n    since    datetime\n  }\n")
	b.WriteString("  filter    storeId==args.storeId && isNotDeleted && actor.isClusterOwner==true && when(args.since) { updatedAt>=args.since }\n")
	b.WriteString("  sort      \"updatedAt\", \"desc\"\n")
	b.WriteString("  paginate  100\n")
	fmt.Fprintf(&b, "  shape     %s\n", shapeName(p))
	b.WriteString("}\n")
	return b.String()
}

// Construct names. Prefix-first so every generated name sorts together and
// nothing collides with a hand-written construct in another domain.
func shapeName(p *TypePlan) string     { return p.Concept + "Mirror" }
func byGidName(p *TypePlan) string     { return "shopify" + title(p.Concept) + "ByGid" }
func forStoreName(p *TypePlan) string  { return "shopify" + title(p.Concept) + "ForStore" }

func title(s string) string {
	if s == "" {
		return s
	}
	return strings.ToUpper(s[:1]) + s[1:]
}

func pad(s string, n int) string {
	for len(s) < n {
		s += " "
	}
	return s
}

// wrapComment / wrapDoc render prose as `//` and `///` blocks.
func wrapComment(s string) string { return prefixed(s, "// ") }
func wrapDoc(s string) string     { return prefixed(s, "/// ") }

func prefixed(s, prefix string) string {
	var b strings.Builder
	for _, line := range wrapLines(s, 72) {
		b.WriteString(prefix + line + "\n")
	}
	return b.String()
}

func wrapLines(s string, width int) []string {
	words := strings.Fields(s)
	if len(words) == 0 {
		return []string{""}
	}
	var out []string
	cur := words[0]
	for _, w := range words[1:] {
		if len(cur)+1+len(w) > width {
			out = append(out, cur)
			cur = w
			continue
		}
		cur += " " + w
	}
	return append(out, cur)
}

// sortedConceptNames is used by the emitters that need a stable domain list.
func sortedConceptNames(plans []*TypePlan) []string {
	out := make([]string, 0, len(plans))
	for _, p := range plans {
		out = append(out, p.Concept)
	}
	sort.Strings(out)
	return out
}
